package com.hardcraft.mobs;
import java.util.*;
record BossDefinition(String id,double baseHealth,double healthPerPlayer,List<Double> phases,double minimumDamage){BossDefinition{if(id==null||!id.matches("[a-z0-9_-]+")||baseHealth<=0||healthPerPlayer<0||minimumDamage<0||phases==null||phases.stream().anyMatch(x->x<=0||x>=1))throw new IllegalArgumentException("invalid boss definition");phases=phases.stream().sorted(Comparator.reverseOrder()).toList();}double maximumHealth(int players){return baseHealth+healthPerPlayer*Math.max(0,players-1);}int phase(double health,double maximum){int phase=1;for(double threshold:phases)if(health/maximum<=threshold)phase++;return phase;}double rescale(double health,double oldMaximum,int players){double next=maximumHealth(players);return Math.max(1,Math.min(next,health/oldMaximum*next));}}
final class BossRules{private BossRules(){}static Set<UUID> eligible(Map<UUID,Double> damage,double minimum){Set<UUID> out=new HashSet<>();damage.forEach((id,value)->{if(value>=minimum)out.add(id);});return Set.copyOf(out);}}